import sys
from bisect import bisect_right

def main():
    data = sys.stdin.read().split()
    length, q = int(data[0]), int(data[1])
    ids = {}
    vals = {}
    cur = 0
    out = []
    p = 2
    for _ in range(q):
        op = data[p]
        if op == 'set':
            i, v = int(data[p + 1]), int(data[p + 2])
            p += 3
            if i in ids:
                if ids[i][-1] == cur:
                    vals[i][-1] = v
                else:
                    ids[i].append(cur)
                    vals[i].append(v)
            else:
                ids[i] = [cur]
                vals[i] = [v]
        elif op == 'snap':
            p += 1
            out.append(cur)
            cur += 1
        else:
            i, s = int(data[p + 1]), int(data[p + 2])
            p += 3
            if i in ids:
                k = bisect_right(ids[i], s) - 1
                out.append(vals[i][k] if k >= 0 else 0)
            else:
                out.append(0)
    print('\n'.join(map(str, out)))

main()

