def gen(rng):
    def fmt(length, ops):
        return f'{length} {len(ops)}\n' + '\n'.join(ops)

    def make(length, q, w_set, w_snap, w_get, maxv=10**9, hot=None):
        ops, snaps = [], 0
        for _ in range(q):
            r = rng.random() * (w_set + w_snap + w_get)
            idx = rng.randrange(length) if hot is None else rng.randrange(min(hot, length))
            if r < w_set:
                ops.append(f'set {idx} {rng.randint(0, maxv)}')
            elif r < w_set + w_snap or snaps == 0:
                ops.append('snap')
                snaps += 1
            else:
                ops.append(f'get {idx} {rng.randrange(snaps)}')
        if snaps == 0:
            ops[-1] = 'snap'
        return ops

    tests = [
        fmt(3, ['set 0 5', 'snap', 'set 0 6', 'get 0 0', 'snap', 'get 0 1', 'get 1 1']),
        fmt(2, ['set 1 4', 'set 1 9', 'snap', 'set 1 2', 'get 1 0', 'snap', 'get 1 1', 'get 0 0']),
        fmt(1, ['snap']),
        fmt(1, ['snap', 'get 0 0']),
        fmt(1, ['set 0 7', 'set 0 0', 'snap', 'get 0 0']),
        fmt(2, ['snap', 'snap', 'set 0 3', 'snap', 'get 0 0', 'get 0 1', 'get 0 2', 'get 1 2']),
        fmt(5, ['set 4 10**9'.replace('10**9', '1000000000'), 'snap', 'set 4 1', 'snap', 'get 4 0', 'get 4 1']),
    ]
    for length in (1, 2, 3, 5, 8):
        for q in (6, 12, 25):
            tests.append(fmt(length, make(length, q, 3, 2, 3, maxv=9)))
    N = 100000
    tests.append(fmt(N, make(N, N, 1, 1, 1)))
    tests.append(fmt(N, make(N, N, 1, 3, 1, hot=50)))
    tests.append(fmt(N, make(N, N, 2, 5, 3)))
    tests.append(fmt(N, ['snap'] * 30000 + make(N, N - 30000, 2, 0.01, 3, hot=1000)))
    return tests

